from typing import Dict, Tuple

def solve_math_problem(n: int) -> int:
    """
    Calculates the number of sequences {a_i} of length n such that
    a_1 = a_n = 1 and a_{i+1}/a_i in {2, 1, -1/2}.

    Let a_i = 2^{x_i}. Then x_{i+1} - x_i in {1, 0, -1}.
    This is equivalent to a path of length n-1 starting at 0 and ending at 0,
    where each step is in {1, 0, -1}.
    """
    if n < 1:
        return 0
    if n == 1:
        return 1

    # dp[step][current_value] = number of ways
    # Since the path length is n-1, the value can range from -(n-1) to (n-1)
    dp: Dict[int, int] = {0: 1}

    for _ in range(n - 1):
        new_dp: Dict[int, int] = {}
        for val, count in dp.items():
            for step in [-1, 0, 1]:
                new_val = val + step
                new_dp[new_val] = new_dp.get(new_val, 0) + count
        dp = new_dp

    return dp.get(0, 0)

