def get_largest_odd_factor(n: int) -> int:
    """Returns the largest odd factor of a positive integer n."""
    if n <= 0:
        raise ValueError("Input must be a positive integer.")
    while n % 2 == 0:
        n //= 2
    return n

def is_supereven(n: int) -> bool:
    """Checks if a positive integer n is supereven."""
    d = get_largest_odd_factor(n)
    return d < (n / d)

def solve_math_problem(limit: int) -> int:
    """Counts the number of supereven positive integers less than limit."""
    if not isinstance(limit, int) or limit <= 0:
        raise ValueError("Limit must be a positive integer.")

    count = 0
    for i in range(1, limit):
        if is_supereven(i):
            count += 1
    return count

